import {
  canConnect,
  defaultNodeName,
  type NodeType,
  type TransformConfig,
  type TransformOperation,
  type Workflow,
  type WorkflowNode,
} from '@wand/shared'

// Editor state = the workflow document (persisted, sent to the server on Run) plus
// UI-only selection (never persisted, never counts as an edit). Pure: IDs are
// generated by the caller so the reducer stays deterministic and testable.

export type Selection = { kind: 'node'; id: string } | { kind: 'edge'; id: string } | null

export interface EditorState {
  workflow: Workflow
  selection: Selection
}

type XY = { x: number; y: number }

export type EditorAction =
  | { type: 'addNode'; id: string; nodeType: NodeType; position: XY }
  | { type: 'moveNode'; id: string; position: XY }
  | { type: 'renameNode'; id: string; name: string }
  | { type: 'setInputText'; id: string; text: string }
  | { type: 'setTransformConfig'; id: string; config: TransformConfig }
  | { type: 'connect'; source: string; target: string }
  | { type: 'removeNode'; id: string }
  | { type: 'removeEdge'; id: string }
  | { type: 'select'; selection: Selection }
  /** Clears the selection only if it still points at this element (React Flow emits unselect/select in either order). */
  | { type: 'unselect'; kind: 'node' | 'edge'; id: string }
  | { type: 'replaceWorkflow'; workflow: Workflow }

export const OPERATION_LABELS: Record<TransformOperation, string> = {
  uppercase: 'Uppercase',
  lowercase: 'Lowercase',
  normalize: 'Normalize',
  replace: 'Replace',
}

export function createNode(id: string, type: NodeType, position: XY): WorkflowNode {
  switch (type) {
    case 'input':
      return { id, type, name: defaultNodeName(type), position, config: { text: '' } }
    case 'transform':
      return { id, type, name: OPERATION_LABELS.uppercase, position, config: { operation: 'uppercase' } }
    case 'output':
      return { id, type, name: defaultNodeName(type), position, config: {} }
  }
}

/** Config for a newly chosen operation; keeps Replace's fields if it was already Replace. */
export function configForOperation(operation: TransformOperation, previous: TransformConfig): TransformConfig {
  if (operation !== 'replace') return { operation }
  return previous.operation === 'replace' ? previous : { operation, find: '', replaceWith: '' }
}

export function edgeId(source: string, target: string): string {
  return `e-${source}-${target}`
}

export function exampleWorkflow(): Workflow {
  return {
    name: 'Text processing',
    nodes: [
      { id: 'input-1', type: 'input', name: 'Input', position: { x: 0, y: 0 }, config: { text: 'Hello, Workflow Studio!' } },
      { id: 'transform-1', type: 'transform', name: 'Uppercase', position: { x: 300, y: 0 }, config: { operation: 'uppercase' } },
      { id: 'output-1', type: 'output', name: 'Output', position: { x: 600, y: 0 }, config: {} },
    ],
    edges: [
      { id: edgeId('input-1', 'transform-1'), source: 'input-1', target: 'transform-1' },
      { id: edgeId('transform-1', 'output-1'), source: 'transform-1', target: 'output-1' },
    ],
  }
}

/**
 * When the operation changes, follow it with the name if the user hasn't customised
 * the name (it still equals the old operation's label or the generic default).
 */
function nameAfterOperationChange(node: WorkflowNode, from: TransformOperation, to: TransformOperation): string {
  const untouched = node.name === OPERATION_LABELS[from] || node.name === defaultNodeName('transform')
  return untouched ? OPERATION_LABELS[to] : node.name
}

function updateNode(state: EditorState, id: string, update: (node: WorkflowNode) => WorkflowNode): EditorState {
  return {
    ...state,
    workflow: {
      ...state.workflow,
      nodes: state.workflow.nodes.map((node) => (node.id === id ? update(node) : node)),
    },
  }
}

function isSelected(selection: Selection, kind: 'node' | 'edge', id: string): boolean {
  return selection?.kind === kind && selection.id === id
}

export function editorReducer(state: EditorState, action: EditorAction): EditorState {
  switch (action.type) {
    case 'addNode':
      return {
        workflow: { ...state.workflow, nodes: [...state.workflow.nodes, createNode(action.id, action.nodeType, action.position)] },
        selection: { kind: 'node', id: action.id },
      }

    case 'moveNode':
      return updateNode(state, action.id, (node) => ({ ...node, position: action.position }))

    case 'renameNode':
      return updateNode(state, action.id, (node) => ({ ...node, name: action.name }))

    case 'setInputText':
      return updateNode(state, action.id, (node) =>
        node.type === 'input' ? { ...node, config: { text: action.text } } : node,
      )

    case 'setTransformConfig':
      return updateNode(state, action.id, (node) =>
        node.type === 'transform'
          ? {
              ...node,
              name: nameAfterOperationChange(node, node.config.operation, action.config.operation),
              config: action.config,
            }
          : node,
      )

    case 'connect': {
      // Defensive: the canvas already gates connections with canConnect.
      if (!canConnect(state.workflow, action.source, action.target).ok) return state
      const edge = { id: edgeId(action.source, action.target), source: action.source, target: action.target }
      return { ...state, workflow: { ...state.workflow, edges: [...state.workflow.edges, edge] } }
    }

    case 'removeNode': {
      if (!state.workflow.nodes.some((n) => n.id === action.id)) return state
      const removedEdgeIds = new Set(
        state.workflow.edges.filter((e) => e.source === action.id || e.target === action.id).map((e) => e.id),
      )
      const selection = state.selection
      const selectionRemoved =
        isSelected(selection, 'node', action.id) || (selection?.kind === 'edge' && removedEdgeIds.has(selection.id))
      return {
        workflow: {
          ...state.workflow,
          nodes: state.workflow.nodes.filter((n) => n.id !== action.id),
          edges: state.workflow.edges.filter((e) => !removedEdgeIds.has(e.id)),
        },
        selection: selectionRemoved ? null : selection,
      }
    }

    case 'removeEdge':
      if (!state.workflow.edges.some((e) => e.id === action.id)) return state
      return {
        workflow: { ...state.workflow, edges: state.workflow.edges.filter((e) => e.id !== action.id) },
        selection: isSelected(state.selection, 'edge', action.id) ? null : state.selection,
      }

    case 'select':
      return { ...state, selection: action.selection }

    case 'unselect':
      return isSelected(state.selection, action.kind, action.id) ? { ...state, selection: null } : state

    case 'replaceWorkflow':
      return { workflow: action.workflow, selection: null }
  }
}
